def few_shot(examples, query):
    blocks = [f'Input: {inp}\nOutput: {out}' for inp, out in examples]
    blocks.append(f'Input: {query}\nOutput:')
    return '\n\n'.join(blocks)

def json_instruction(schema_keys):
    keys = ', '.join(schema_keys)
    return f'Respond with JSON containing keys: {keys}.'

def extract_json(text):
    start = text.find('{')
    end = text.rfind('}')
    if start == -1 or end == -1 or end < start:
        raise ValueError('no json object')
    return text[start:end + 1]

